import{_ as t,o as l,c as e,a2 as i}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"추천 로컬 모델","description":"VRAM별 로컬 LLM 추천（경로 검증, 롤플레이, 중국어）; Ollama, LM Studio, KoboldCPP, llama.cpp + MiniTavern.","frontmatter":{"title":"추천 로컬 모델","description":"VRAM별 로컬 LLM 추천（경로 검증, 롤플레이, 중국어）; Ollama, LM Studio, KoboldCPP, llama.cpp + MiniTavern.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"추천 로컬 모델 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"VRAM별 로컬 LLM 추천（경로 검증, 롤플레이, 중국어）; Ollama, LM Studio, KoboldCPP, llama.cpp + MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/local/models"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/local/models"}]]},"headers":[],"relativePath":"ko/local/models.md","filePath":"ko/local/models.md","lastUpdated":1787224147000}'),o={name:"ko/local/models.md"};function n(r,a,d,s,h,p){return l(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="추천-모델" tabindex="-1">추천 모델 <a class="header-anchor" href="#추천-모델" aria-label="Permalink to &quot;추천 모델&quot;">​</a></h1><p>모델명·다운로드는 도구마다 다릅니다. 아래는 <strong>규모와 용도</strong> 제안. pull / 파일명은 각 도구 페이지 기준.</p><h2 id="하드웨어별-규모" tabindex="-1">하드웨어별 규모 <a class="header-anchor" href="#하드웨어별-규모" aria-label="Permalink to &quot;하드웨어별 규모&quot;">​</a></h2><table tabindex="0"><thead><tr><th>대략 규모</th><th>메모리/VRAM 대략</th><th>적합</th></tr></thead><tbody><tr><td>1B–3B</td><td>약 4–8GB</td><td><strong>경로 먼저 검증</strong>, 저사양</td></tr><tr><td>7B–9B</td><td>약 8–16GB</td><td>롤플레이 스위트 스팟</td></tr><tr><td>12B–14B</td><td>16GB+</td><td>품질↑, 속도는 GPU</td></tr><tr><td>32B+</td><td>24GB+ 또는 강한 양자화</td><td>고사양; 폰 연결도 대기↑</td></tr></tbody></table><p>양자화（Q4 / Q5 / IQ 등）가 작을수록 자원↓·품질 소폭↓. GGUF는 커뮤니티 흔한 <code>Q4_K_M</code> / <code>Q5_K_M</code> 우선.</p><h2 id="경로-검증-작은-모델-우선" tabindex="-1">경로 검증（작은 모델 우선） <a class="header-anchor" href="#경로-검증-작은-모델-우선" aria-label="Permalink to &quot;경로 검증（작은 모델 우선）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>장면</th><th>Ollama 예</th><th>GGUF / 기타</th></tr></thead><tbody><tr><td>최단 검증</td><td><code>llama3.2:3b</code>, <code>qwen2.5:3b</code></td><td>임의 3B급 instruct GGUF</td></tr><tr><td>중국어 경량</td><td><code>qwen2.5:3b</code> / <code>qwen2.5:7b</code></td><td>Qwen2.5 Instruct 양자화</td></tr></tbody></table><p>먼저 <a href="/ultra_guides/ko/connect-app/minitavern">연결 테스트 성공</a>, 그다음 큰 모델.</p><h2 id="롤플레이-팁" tabindex="-1">롤플레이 팁 <a class="header-anchor" href="#롤플레이-팁" aria-label="Permalink to &quot;롤플레이 팁&quot;">​</a></h2><ul><li><strong>Instruct / Chat</strong> 파인튜닝 우선, 순수 베이스 완성 모델 비권장.</li><li>커뮤니티 RP 가중치는 시간에 따라 변함; 도구에서 안정 로드·충분한 컨텍스트가 기준.</li><li>컨텍스트가 작으면 장설정/월드북이 잘림; 7B는 4k–8k부터, VRAM에 맞춰 확대.</li><li>MiniTavern <strong>모델명</strong>은 도구 목록과 <strong>완전 일치</strong>（tag 포함, 예 <code>:7b</code>）.</li></ul><h2 id="ollama-자주-쓰는-pull" tabindex="-1">Ollama 자주 쓰는 pull <a class="header-anchor" href="#ollama-자주-쓰는-pull" aria-label="Permalink to &quot;Ollama 자주 쓰는 pull&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:7b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:14b</span></span></code></pre></div><p>더 보기: <a href="/ultra_guides/ko/ollama/models">Ollama · 다운로드와 선택</a>.</p><h2 id="lm-studio-koboldcpp-llama-cpp" tabindex="-1">LM Studio / KoboldCPP / llama.cpp <a class="header-anchor" href="#lm-studio-koboldcpp-llama-cpp" aria-label="Permalink to &quot;LM Studio / KoboldCPP / llama.cpp&quot;">​</a></h2><ol><li><a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a> 등에서 <strong>GGUF</strong>（라이선스·출처 주의）.</li><li>해당 도구에서 같은 파일 로드.</li><li>API / Server 켠 뒤 표시 <strong>model id</strong>를 MiniTavern에.</li></ol><h2 id="다음" tabindex="-1">다음 <a class="header-anchor" href="#다음" aria-label="Permalink to &quot;다음&quot;">​</a></h2><p><a href="./tools">도구 개요</a> → 선택한 도구의 「서비스」장 → <a href="/ultra_guides/ko/connect-app/minitavern">MiniTavern 설정</a></p>`,17)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
